INSERT INTO `daily_tasks` (`id`, `weekday`, `branchId`, `title`, `description`, `isActive`, `sortOrder`, `createdAt`) VALUES
(1, 0, NULL, 'Ревизия аудио-периферии', 'Дневная смена (1–15): протереть амбушюры всех наушников, проверить провода, зафиксировать стяжкой. Хрипы и поломки — в тех. чат.', 1, 0, '2026-08-29T17:53:41.300Z'),
(2, 1, NULL, 'Пополнение и чистота витрин', 'Проверить холодильники и полки со снеками, пополнить со склада, протереть витрины.', 1, 1, '2026-08-29T17:53:41.304Z'),
(3, 2, NULL, 'Порядок зоны администратора', 'Дневная смена (1–15): разобрать тумбочки, выбросить лишние бумаги, протереть пыль. Забытые вещи гостей — в «Потеряшки».', 1, 2, '2026-08-29T17:53:41.307Z'),
(4, 3, NULL, 'Верхние полки и декор', 'Протирка верхних полок и элементов декора, до которых не доходят руки при ежедневной уборке.', 1, 3, '2026-08-29T17:53:41.309Z'),
(5, 4, NULL, 'Хоз. Аудит', 'Дневная смена (1–15): инвентаризация расходников, список закупок руководителю.', 1, 4, '2026-08-29T17:53:41.310Z'),
(6, 5, NULL, 'Глубокая мойка FoodZone', 'Полная очистка зоны приёма пищи, протирка холодильников, полок со снеками, микроволновки.', 1, 5, '2026-08-29T17:53:41.312Z'),
(7, 6, NULL, 'Уход за креслами', 'Протирка крестовин и обивки игровых кресел в одной из зон, отчёт с фото.', 1, 6, '2026-08-29T17:53:41.313Z'),
(8, 6, NULL, '123', 'Дневная смена (1–15): протереть амбушюры всех наушников, проверить провода, зафиксировать стяжкой. Хрипы и поломки — в тех. чат.', 1, 0, '2026-08-31T15:24:20.626Z'),
(9, 0, NULL, 'Дневная смена (1–15): протереть амбушюры всех наушников, проверить провода, зафиксировать стяжкой. Хрипы и поломки — в тех. чат.', '123', 1, 0, '2026-08-31T15:24:28.225Z');
