INSERT INTO `knowledge_articles` (`id`, `categoryId`, `title`, `slug`, `contentHtml`, `kind`, `isDraft`, `sortOrder`, `updatedByUserId`, `createdAt`, `updatedAt`) VALUES
(18, 1, 'Лист штрафов', 'fines', '<p>Штрафы применяются за нарушение настоящей инструкции. При регулярных нарушениях сотрудник отстраняется от смен с последующим увольнением. Суммы в рублях.</p>\n<h2>Негативные отзывы</h2>\n<p>За негативный отзыв гостя (карты, соцсети, прямой отзыв) предусмотрен штраф в размере <strong>двойной суммы урегулирования конфликта</strong> с гостем.</p>', 'fines', 0, 0, NULL, '2026-08-29T18:43:48.208Z', '2026-08-29T19:25:18.768Z'),
(19, 8, 'Приветствие', 'privetstvie', '<p>Приветствуем тебя, наш будущий коллега! Перед тобой полная база знаний администратора компьютерного клуба GAMERPRO. Здесь собрано всё: обязанности, регламенты уборки, порядок передачи смены, работа с кассой и LANGAME, прайс, правила и лист штрафов.</p>\n<p>Стажировка — важнейшая часть работы администратора. На этом этапе формируется понимание всей специфики работы клуба. Подходи к обучению с максимальной ответственностью: задавай как можно больше вопросов сопровождающему администратору и внимательно изучай каждый раздел этой инструкции.</p>\n<blockquote><p><strong>Как пользоваться этой базой</strong></p><p>Слева — навигация по разделам. Сверху — поиск: начни печатать, и вики найдёт нужный раздел.</p></blockquote>\n<h2>Цель работы администратора</h2>\n<p>Администратор — лицо клуба. Твоя цель: чтобы каждый гость получил чистое место, исправную технику, вежливое обслуживание и захотел вернуться. Выручка клуба напрямую зависит от того, насколько хорошо ты выполняешь регламенты из этой инструкции.</p>', 'article', 0, 0, NULL, '2026-08-29T19:25:17.538Z', '2026-08-29T19:25:17.538Z'),
(20, 8, 'Внешний вид сотрудника', 'vneshniy-vid', '<p>Администратор заступает на смену в опрятном виде. Внешний вид — часть сервиса.</p>\n<ul data-type="taskList"><li><label></label><p>Чистая, не рваная одежда без резких запахов</p></li><li><label></label><p>Аккуратная причёска, чистые руки</p></li><li><label></label><p>Нейтральный запах: без сильного парфюма, без запаха сигарет</p></li></ul>\n<blockquote data-variant="fine"><p><strong>Штраф</strong></p><p>Заступление на смену в неопрятном виде (запах, рваная и грязная одежда) — 800 ₽.</p></blockquote>', 'article', 0, 1, NULL, '2026-08-29T19:25:17.541Z', '2026-08-29T19:25:17.541Z'),
(21, 8, 'Обязанности администратора', 'obyazannosti-administratora', '<p>Полный перечень обязанностей администратора клуба GAMERPRO. Их выполнение проверяется руководством и фиксируется в отчётах.</p>\n<ol><li><p>Осуществлять приём и передачу смены по регламенту (см. раздел «Передача смены»).</p></li><li><p>Принимать оплату от гостей за игровое время и товары; пополнять игровой баланс гостя в LANGAME на оплаченную сумму.</p></li><li><p>Вести учёт товара: принимать поставки по накладным, корректно оприходовать их, оформлять документы (см. раздел «Приём поставок»).</p></li><li><p>Обеспечивать бесперебойную работу оборудования, периферии и ПО (LANGAME); находиться на рабочем месте в течение всей смены.</p></li><li><p>Содержать клуб в чистоте самостоятельно и контролировать работу уборщицы.</p></li><li><p>Убирать игровое место после каждой завершённой сессии — строго по регламенту (см. «Уборка места после гостя»).</p></li><li><p>Каждые 2 часа делать обход игровых мест и уборной комнаты для контроля чистоты и порядка.</p></li><li><p>Пополнять холодильники, полки и стеллажи товаром в течение всей смены.</p></li><li><p>Знать сборки всех ПК и комплектации периферии, представленные в клубе.</p></li><li><p>Знать систему лояльности, все действующие скидки и акции клуба.</p></li><li><p>Требовать от гостей соблюдения «Правил посещения компьютерного клуба».</p></li><li><p>Доброжелательно общаться с гостями и коллегами, подавать личный пример качественного обслуживания. Проявлять внимательность, терпеливость и вежливость.</p></li><li><p>При конфликтных и внештатных ситуациях принимать меры к их прекращению и незамедлительно докладывать руководству (см. «Конфликтные ситуации»).</p></li></ol>\n<blockquote><p><strong>Обход каждые 2 часа</strong></p><p>Обход — не формальность. Проверяй: мусор на столах, состояние периферии, работу кондиционеров, чистоту уборной, наличие туалетных принадлежностей.</p></blockquote>', 'article', 0, 2, NULL, '2026-08-29T19:25:17.543Z', '2026-08-29T19:25:17.543Z'),
(22, 9, 'Распорядок дня: дневная смена', 'dnevnaya-smena', '<p>Дневная смена администратора: с 08:00 до 20:00.</p>\n<table><thead><tr><th>Время</th><th>Что делаешь</th></tr></thead><tbody><tr><td>07:45–08:00</td><td>Приход в клуб, приём смены у ночного администратора по чек-листу передачи смены</td></tr><tr><td>08:00–14:00</td><td>Выполнение «Задания дня» в период низкой загрузки + отчёт с хэштегом в рабочий чат</td></tr><tr><td>Каждые 2 часа</td><td>Обход игровых мест и уборной комнаты</td></tr><tr><td>В течение смены</td><td>Уборка мест после каждого гостя (максимум 20 минут с момента ухода), пополнение холодильников и полок, продажи, помощь гостям</td></tr><tr><td>За 30 мин до конца</td><td>Подготовка к передаче смены: касса, аудит оборудования, мусор, чистота админ-зоны</td></tr><tr><td>19:45–20:00</td><td>Передача смены ночному администратору</td></tr></tbody></table>\n<blockquote><p><strong>Приоритеты в работе</strong></p><p>Если задачи конфликтуют, порядок такой: 1) гость у стойки / звонок → 2) уборка места после гостя → 3) пополнение витрин → 4) задание дня → 5) прочие задачи.</p></blockquote>', 'article', 0, 0, NULL, '2026-08-29T19:25:17.547Z', '2026-08-29T19:25:17.547Z'),
(23, 9, 'Распорядок дня: ночная смена', 'nochnaya-smena', '<p>Ночная смена администратора: с 20:00 до 08:00.</p>\n<table><thead><tr><th>Время</th><th>Что делаешь</th></tr></thead><tbody><tr><td>19:45–20:00</td><td>Приход, приём смены у дневного администратора по чек-листу</td></tr><tr><td>20:00–00:00</td><td>Заселение ночных пакетов, продажи, контроль зала</td></tr><tr><td>00:00–06:00</td><td>Ночные задания дня (см. «Задание дня»), контроль зала, уборка освободившихся мест</td></tr><tr><td>06:00–07:00</td><td>Сбор мусора по клубу, замена пакетов, вынос мусора</td></tr><tr><td>07:45–08:00</td><td>Передача смены дневному администратору</td></tr></tbody></table>\n<h2>Особые обязанности ночного администратора</h2>\n<ul><li><p>Поставить беспроводные мыши на зарядку — к утру все мыши должны быть заряжены.</p></li><li><p>Следить за кондиционерами: если гости ушли из комнаты (например, в час ночи), кондиционер в ней нужно выключить. Кондиционеры не должны работать впустую всю ночь.</p></li></ul>\n<blockquote data-variant="fine"><p><strong>Сон на рабочем месте</strong></p><p>Сон на смене — штраф 5 000 ₽. Ночная смена — рабочая смена, а не отдых.</p></blockquote>', 'article', 0, 1, NULL, '2026-08-29T19:25:17.549Z', '2026-08-29T19:25:17.549Z'),
(24, 9, 'Передача смены', 'peredacha-smeny', '<p>Передача смены — самый ответственный момент дня. Принимая смену, ты принимаешь на себя ответственность за кассу, товар и оборудование. Всё, что не зафиксировано при приёме, считается твоей зоной ответственности.</p>\n<h2>Чек-лист передачи смены</h2>\n<ul data-type="taskList"><li><label></label><p>Проверить целостность периферии: мыши, клавиатуры, мониторы, наушники — на всех местах</p></li><li><label></label><p>Навести чистоту в помещении: столы, коврики, периферия убраны</p></li><li><label></label><p>Провести влажную уборку стола администратора</p></li><li><label></label><p>Пополнить холодильники, полки и стеллажи</p></li><li><label></label><p>Пересчитать наличные в кассе и сверить с текущим отчётом LANGAME</p></li><li><label></label><p>Сообщить о технических неисправностях ПК и периферии сменщику и вышестоящему руководству</p></li><li><label></label><p>Передать сменщику бытовые детали: например, гость оставил напиток на админке (со своим в зал нельзя — просим оставлять на админке), кто-то оставил телефон на зарядке и т.п.</p></li><li><label></label><p>Проверить работу кондиционеров</p></li><li><label></label><p>Собрать мусор по клубу, поменять пакеты, вынести мусор</p></li><li><label></label><p>Протереть FoodZone</p></li></ul>\n<h2>Касса и деньги</h2>\n<ul><li><p>Сумма в кассе должна совпадать с отчётом LANGAME на момент передачи. Любое расхождение сразу отписывается в рабочий чат.</p></li><li><p>После пересчёта принимающий отправляет в раздел «Отчёты» сообщение с хэштегом: «#Филиал_Принял (Имя)» + фото отчёта LANGAME. Сдающий — «#Филиал_Сдал (Имя)». Подробнее — в разделе «Система хэштегов».</p></li></ul>\n<blockquote data-variant="fine"><p><strong>Штрафы, связанные с пересменкой</strong></p><p>Не проведён аудит оборудования при пересменке — 600 ₽. Мусор на столах / в админке после пересменки — 600 ₽. Не проверено имущество клуба в течение 15 минут после ухода гостя — 300 ₽.</p></blockquote>', 'article', 0, 2, NULL, '2026-08-29T19:25:17.551Z', '2026-08-29T19:25:17.551Z'),
(25, 9, 'Задачи на смене', 'zadachi-na-smene', '<h2>Ресепшен</h2>\n<ul><li><p>Чтение всех новостей перед сменой и во время неё (официальные паблики, чат ADMIN NEWS, рабочие чаты)</p></li><li><p>Приветствие гостей и прощание с ними</p></li><li><p>Обработка обращений гостей по телефону и в соцсетях</p></li><li><p>Продажа товаров и услуг</p></li><li><p>Поддержание чистоты и порядка на ресепшене и во входной группе</p></li><li><p>Зарядка рабочего телефона и геймпадов</p></li><li><p>Контроль за кассой и сейфом</p></li><li><p>Наблюдение за ареной по камерам каждые 15 минут (если невозможно сделать обход по залам)</p></li><li><p>Расстановка новых макетов и поддержание их актуальности</p></li><li><p>Всегда держать открытыми LANGAME, соцсети клуба, рабочие чаты, чат ТП, мониторинг. Оперативно реагировать на сообщения и звонки</p></li><li><p>Приём и сдача смены по чек-листу. Отправление кассового отчёта в конце смены</p></li><li><p>Проверка эвакуационных выходов на доступность</p></li><li><p>Заполнение всех необходимых таблиц</p></li></ul>\n<h2>Бар</h2>\n<ul><li><p>Наполнение холодильников и витрин по стандарту</p></li><li><p>Активная продажа продуктов</p></li><li><p>Поддержание чистоты и порядка в баре</p></li><li><p>Передача руководителю информации о том, какие позиции закончились или заканчиваются</p></li><li><p>Приём товаров</p></li></ul>\n<h2>Игровые залы</h2>\n<ul><li><p>Обход игровых залов каждые 15 минут</p></li><li><p>Уборка игровых мест после каждого гостя</p></li><li><p>Поддержание комфортной атмосферы (музыка, громкость, освещение, температура воздуха, отсутствие неприятных запахов)</p></li><li><p>Контроль за соблюдением правил клуба</p></li><li><p>Регистрация гостей</p></li><li><p>Посадка гостей на игровые сессии и турниры</p></li><li><p>Обновление всех игр и лаунчеров на ПК и PlayStation</p></li><li><p>Настройка и устранение неполадок ПК и PlayStation</p></li><li><p>Контроль за состоянием периферии, кресел и мебели</p></li><li><p>Поддержание чистоты и порядка во всей киберарене</p></li><li><p>Регулярное проведение генеральной уборки игровых мест, периферии и ПК</p></li></ul>\n<h2>Гости</h2>\n<ul><li><p>Экскурсия по арене</p></li><li><p>Консультация по всем вопросам</p></li><li><p>Активное продвижение акций и турниров, проверка промокодов</p></li><li><p>Активные продажи товаров из бара</p></li><li><p>Помощь при возникновении проблем</p></li></ul>', 'article', 0, 3, NULL, '2026-08-29T19:25:17.552Z', '2026-08-29T19:25:17.552Z'),
(26, 10, 'Уборка места после гостя', 'uborka-posle-gostya', '<p>Убирается после КАЖДОГО гостя: клавиатура, мышь, коврик, стол, кресло. Максимальное время — 20 минут с момента ухода гостя. Не закрывай уведомление LANGAME об уходе гостя до завершения уборки.</p>\n<blockquote><p><strong>Главное правило: две разные тряпки</strong></p><p>Строго две разные микрофибры — одна для мебели (стол), вторая только для периферии (мышь, клавиатура). Никогда не путай их.</p></blockquote>\n<ol>\n<li><p><strong>Подготовка</strong></p><p>Отключи клавиатуру от системного блока (или USB-хаба). Убери игровой коврик со стола.</p></li>\n<li><p><strong>Стол</strong></p><p>Нанеси чистящий спрей на поверхность стола. Тщательно протри стол первой тряпкой (для мебели), особое внимание — зонам за монитором и под клавиатурой/ковриком.</p></li>\n<li><p><strong>Коврик</strong></p><p>Стряхни крошки с коврика на пол. Верни коврик на место. При видимых загрязнениях протри влажной тряпкой.</p></li>\n<li><p><strong>Периферия</strong></p><p>Возьми вторую тряпку (только для девайсов) и брызгалку с чистящим средством. Пшикни один-два раза на клавиатуру и мышь (или на саму тряпку) и протри. После протирки проверь рукой, что поверхность не жирная — при необходимости пройди ещё раз. Подключи клавиатуру обратно.</p></li>\n<li><p><strong>Монитор</strong></p><p>При необходимости протри экран от капель и разводов специальной салфеткой с чистящим средством для стёкол.</p></li>\n<li><p><strong>Финал</strong></p><p>Положи новую индивидуальную влажную салфетку поверх клавиатуры для следующего гостя. Проверь симметричность расстановки девайсов и кресла.</p></li>\n</ol>\n<blockquote data-variant="fine"><p><strong>Штраф</strong></p><p>Грязный стол после гостя / плохая уборка (не по регламенту) — 1 500 ₽.</p></blockquote>', 'article', 0, 0, NULL, '2026-08-29T19:25:17.556Z', '2026-08-29T19:25:17.556Z'),
(27, 10, 'Задание дня', 'zadanie-dnya', '<p>Задание дня выполняется в дополнение к основной уборке игровых мест. Время выполнения для дневной смены: с 08:00 до 14:00 (период низкой загрузки). По завершении — отчёт в раздел «Отчёт по уборке» с хэштегом.</p>\n<blockquote><p><strong>Формат отчёта</strong></p><p>Хэштег #Филиал_Уборка (вместо «Филиал» — название твоей точки) + описание сделанного + фото-подтверждение. Фото обязательно всегда, кроме протирки мониторов. Примеры: «#Гондатти_Уборка Протер мониторы 25 штук», «#Газовиков_Уборка Почистил 4 клавиатуры из 25 [Фото]».</p></blockquote>\n<h2>Первая половина месяца (1–15 число)</h2>\n<table><thead><tr><th>День</th><th>Смена</th><th>Задание</th></tr></thead><tbody><tr><td>Понедельник</td><td>День</td><td>Ревизия аудио-периферии: протереть амбушюры всех наушников, проверить провода. Длинные/путающиеся кабели собрать и зафиксировать стяжкой. Выявить хрипы и поломки.</td></tr><tr><td>Понедельник</td><td>Ночь</td><td>Глубокая мойка FoodZone: полная очистка зоны приёма пищи, протирка холодильников снаружи и внутри, полок со снеками, микроволновки.</td></tr><tr><td>Среда</td><td>День</td><td>Порядок зоны администратора: разобрать тумбочки, выбросить лишние бумаги, протереть пыль на полках. Забытые вещи гостей — в «Потеряшки».</td></tr><tr><td>Среда</td><td>Ночь</td><td>Протирка мониторов: тщательная протирка всех мониторов спецсредством. Устранение разводов и пыли на рамках.</td></tr><tr><td>Пятница</td><td>День</td><td>Хоз. аудит: полная инвентаризация склада расходников (салфетки, туалетная бумага, мыло, мешки для мусора, чистящие средства). Список закупок — руководителю.</td></tr><tr><td>Пятница</td><td>Ночь</td><td>Уход за креслами: протирка крестовин, удаление загрязнений с обивки игровых кресел в одной из зон.</td></tr></tbody></table>\n<h2>Вторая половина месяца (16–31 число)</h2>\n<table><thead><tr><th>День</th><th>Смена</th><th>Задание</th></tr></thead><tbody><tr><td>Понедельник</td><td>День</td><td>Глубокая мойка FoodZone + ревизия аудио-периферии (наушники, провода, стяжки, выявление хрипов).</td></tr><tr><td>Среда</td><td>День</td><td>Протирка мониторов спецсредством, устранение разводов и пыли на рамках.</td></tr><tr><td>Среда</td><td>Ночь</td><td>Порядок зоны администратора: тумбочки, полки, «Потеряшки».</td></tr><tr><td>Пятница</td><td>День</td><td>Уход за креслами: крестовины и обивка в одной из зон.</td></tr><tr><td>Пятница</td><td>Ночь</td><td>Хоз. аудит склада расходников, список закупок — руководителю.</td></tr><tr><td>Четверг</td><td>День/Ночь</td><td>Раз в месяц по поручению руководства: протирка верхних полок и элементов декора, до которых не доходят руки при ежедневной уборке.</td></tr></tbody></table>\n<h2>Как правильно протирать (техника)</h2>\n<p>Эти приёмы применяются при выполнении заданий дня. Обрати особое внимание на мониторы — их часто протирают неправильно.</p>\n<ul><li><p>Мониторы: СНАЧАЛА выключи монитор с кнопки — на выключенном экране видны все разводы и пыль. Экран протирай только специальной салфеткой с чистящим средством для экранов. Рамку, подставку и заднюю панель — отдельной влажной микрофиброй. В конце убери разводы сухой микрофиброй.</p></li><li><p>Наушники: протри амбушюры, пластик и оголовье чистой тряпкой с чистящим средством. Заодно проверь провод и звук — хрипы фиксируй в тех. чат.</p></li><li><p>Клавиатуры и мыши: пшикни чистящим средством один-два раза на девайс или на тряпку и протри. После — проверь рукой, что поверхность не жирная.</p></li><li><p>Экраны телевизоров: так же, как мониторы — специальной салфеткой, разводы убрать сухой микрофиброй.</p></li></ul>\n<h2>Периодические задачи</h2>\n<ul><li><p>Технический обход (раз в две недели, по понедельникам): проверка и ручное обновление всех лаунчеров (Steam, Battle.net, Epic Games, Faceit и др.) на всех ПК.</p></li><li><p>Чистка клавиатур (каждое 25-е число): генеральная чистка — полное снятие кейкапов, удаление мусора из корпуса, протирка свитчей, сборка. Объём делится поровну между 4 администраторами. Отчёт: #Филиал_Уборка Чистка клавиатур завершена (ПК №…).</p></li></ul>\n<blockquote data-variant="fine"><p><strong>Штрафы</strong></p><p>Не выполнено задание дня — 400 ₽, повторно — 600 ₽. Не отписано о завершении в соответствующий раздел — 200 ₽, повторно — 400 ₽.</p></blockquote>', 'article', 0, 1, NULL, '2026-08-29T19:25:17.557Z', '2026-08-29T19:25:17.557Z'),
(28, 11, 'Прайс и тарифы', 'prais-i-tarify', '<p>Администратор обязан знать прайс наизусть. Предоставление недостоверной информации гостю — штраф 200 ₽ (повторно 600 ₽). Цены в рублях.</p>\n<p>Ниже — пакеты обоих филиалов с актуальных прайс-листов. Железо зон и поминутный тариф — в карточках «Гондатти» и «Киевская». Быстрый просмотр пакетов также в разделе меню «Тарифы».</p>\n<h2>Гондатти — пакеты</h2>\n<p>ул. Николая Гондатти, 5/2</p>\n<table><thead><tr><th>Пакет</th><th>Standart</th><th>VIP</th><th>Duo / Trio</th></tr></thead><tbody><tr><td>1 час</td><td>120 ₽</td><td>170 ₽</td><td>200 ₽</td></tr><tr><td>3 часа</td><td>300 ₽</td><td>450 ₽</td><td>500 ₽</td></tr><tr><td>5 часов</td><td>480 ₽</td><td>750 ₽</td><td>800 ₽</td></tr><tr><td>Ночь 12 часов (22:00–10:00)</td><td>600 ₽</td><td>850 ₽</td><td>1200 ₽</td></tr></tbody></table>\n<h2>Киевская — пакеты</h2>\n<p>ул. Киевская, 62</p>\n<table><thead><tr><th>Пакет</th><th>Standart</th><th>Comfort</th><th>VIP</th></tr></thead><tbody><tr><td>1 час</td><td>120 ₽</td><td>150 ₽</td><td>160 ₽</td></tr><tr><td>3 часа</td><td>300 ₽</td><td>400 ₽</td><td>430 ₽</td></tr><tr><td>5 часов</td><td>480 ₽</td><td>580 ₽</td><td>640 ₽</td></tr><tr><td>Ночь 12 часов (22:00–10:00)</td><td>600 ₽</td><td>750 ₽</td><td>800 ₽</td></tr></tbody></table>\n<blockquote><p><strong>Система лояльности</strong></p><p>Бонусная программа, уровни гостей и калькулятор кэшбека — в разделе «Бонусная система» портала. Администратор обязан знать все уровни и действующие акции.</p></blockquote>', 'article', 0, 0, '3GD1NXiD1yFkQakcUzqWF8zaDl4wWYDG', '2026-08-29T19:25:17.561Z', '2026-08-31T16:41:22.235Z'),
(29, 12, 'Гондатти: зоны, железо и тарифы', 'gondatti-zony', '<h2>Характеристики зон</h2>\n<table><thead><tr><th></th><th>Standart</th><th>VIP 1</th><th>VIP 2</th><th>Trio</th><th>Duo</th></tr></thead><tbody><tr><td>Процессор</td><td>i5-10400F</td><td>Ryzen 7700</td><td>Ryzen 7700</td><td>i5-12400F</td><td>i5-12400F</td></tr><tr><td>Видеокарта</td><td>RTX 2060</td><td>RTX 5060 Ti</td><td>RTX 5060 Ti</td><td>RX 7700 XT 12 ГБ</td><td>RX 7700 XT 12 ГБ</td></tr><tr><td>Оперативная память</td><td>16 ГБ</td><td>32 ГБ (5600 МГц)</td><td>32 ГБ (5600 МГц)</td><td>32 ГБ (5600 МГц)</td><td>32 ГБ (5600 МГц)</td></tr><tr><td>Мышь</td><td>Logitech G102</td><td>VGN F1</td><td>VGN Moba</td><td>Logitech G Pro Superlight</td><td>Logitech G Pro Superlight</td></tr><tr><td>Клавиатура</td><td>Zone 51</td><td>RedSquare TKL</td><td>Dark Project Sapphire</td><td>Dark Project KD87</td><td>Dark Project KD87</td></tr><tr><td>Наушники</td><td>HyperX Cloud Alpha 2</td><td>HyperX Cloud Alpha 2</td><td>HyperX Cloud Alpha S</td><td>HyperX Cloud Alpha 2</td><td>HyperX Cloud Alpha 2</td></tr><tr><td>Монитор</td><td>BenQ 2411, 144 Гц, 24.5″</td><td>BenQ 2546, 240 Гц, 24.5″</td><td>LG, 240 Гц, 27″</td><td>Asus ROG Strix, 380 Гц, 25″</td><td>Asus ROG Strix, 380 Гц, 25″</td></tr><tr><td>Кресло</td><td>Zone 51 Clubpoint</td><td>Zone 51 Arena</td><td>Zone 51 Armada</td><td>Zone 51 Armada</td><td>Zone 51 Imperial</td></tr></tbody></table>\n<h2>Пакеты</h2>\n<table><thead><tr><th></th><th>Standart</th><th>VIP 1 / VIP 2</th><th>Trio / Duo</th></tr></thead><tbody><tr><td>1 час</td><td>120 ₽</td><td>170 ₽</td><td>200 ₽</td></tr><tr><td>3 часа (пакет)</td><td>300 ₽</td><td>450 ₽</td><td>500 ₽</td></tr><tr><td>5 часов (пакет)</td><td>480 ₽</td><td>750 ₽</td><td>800 ₽</td></tr><tr><td>Ночь, 12 часов (22:00–10:00)</td><td>600 ₽</td><td>850 ₽</td><td>1200 ₽</td></tr></tbody></table>\n<blockquote><p><strong>VIP 1 и VIP 2</strong></p><p>Цена одна для обеих VIP-зон. Отличие — в железе: в <strong>VIP 2</strong> мониторы 27″ (LG, 240 Гц), в <strong>VIP 1</strong> — 24.5″ (BenQ 2546, 240 Гц).</p></blockquote>\n<h2>Базовый тариф по минутам</h2>\n<table><thead><tr><th></th><th>Standart</th><th>VIP 1 / VIP 2</th><th>Trio / Duo</th></tr></thead><tbody><tr><td>20 минут</td><td>40 ₽</td><td>57 ₽</td><td>67 ₽</td></tr><tr><td>30 минут</td><td>60 ₽</td><td>85 ₽</td><td>100 ₽</td></tr><tr><td>40 минут</td><td>80 ₽</td><td>114 ₽</td><td>134 ₽</td></tr><tr><td>50 минут</td><td>100 ₽</td><td>142 ₽</td><td>167 ₽</td></tr><tr><td>1 час</td><td>120 ₽</td><td>170 ₽</td><td>200 ₽</td></tr><tr><td>1 час 30 минут</td><td>180 ₽</td><td>255 ₽</td><td>300 ₽</td></tr><tr><td>2 часа</td><td>240 ₽</td><td>340 ₽</td><td>400 ₽</td></tr></tbody></table>\n<blockquote><p><strong>Пакет выгоднее</strong></p><p>Пакет выгоднее для гостя, чем то же время по базовому тарифу. Если гость берёт три часа и больше — предлагайте пакет.</p></blockquote>', 'article', 0, 0, NULL, '2026-08-29T19:25:17.564Z', '2026-08-31T16:41:22.241Z'),
(30, 12, 'Киевская: зоны, железо и тарифы', 'kievskaya-zony', '<h2>Характеристики зон</h2>\n<table><thead><tr><th></th><th>Standart</th><th>Comfort</th><th>VIP</th></tr></thead><tbody><tr><td>Процессор</td><td>i3-12100F</td><td>i5-11400F</td><td>i5-12400F</td></tr><tr><td>Видеокарта</td><td>RTX 3050</td><td>RTX 3070</td><td>RTX 3070</td></tr><tr><td>Оперативная память</td><td>16 ГБ</td><td>32 ГБ</td><td>32 ГБ</td></tr><tr><td>Мышь</td><td>Logitech</td><td>VXE</td><td>VXE</td></tr><tr><td>Клавиатура</td><td>Dark Project</td><td>Dark Project</td><td>Dark Project</td></tr><tr><td>Наушники</td><td>HyperX</td><td>HyperX</td><td>HyperX</td></tr><tr><td>Монитор</td><td>BenQ Zowie, 144 Гц</td><td>BenQ Zowie, 240 Гц</td><td>BenQ Zowie, 240 Гц</td></tr></tbody></table>\n<h2>Пакеты</h2>\n<table><thead><tr><th></th><th>Standart</th><th>Comfort</th><th>VIP</th></tr></thead><tbody><tr><td>1 час</td><td>120 ₽</td><td>150 ₽</td><td>160 ₽</td></tr><tr><td>3 часа (пакет)</td><td>300 ₽</td><td>400 ₽</td><td>430 ₽</td></tr><tr><td>5 часов (пакет)</td><td>480 ₽</td><td>580 ₽</td><td>640 ₽</td></tr><tr><td>Ночь, 12 часов (22:00–10:00)</td><td>600 ₽</td><td>750 ₽</td><td>800 ₽</td></tr></tbody></table>\n<h2>Базовый тариф по минутам</h2>\n<table><thead><tr><th></th><th>Standart</th><th>Comfort</th><th>VIP</th></tr></thead><tbody><tr><td>10 минут</td><td>20 ₽</td><td>25 ₽</td><td>27 ₽</td></tr><tr><td>20 минут</td><td>40 ₽</td><td>50 ₽</td><td>54 ₽</td></tr><tr><td>30 минут</td><td>60 ₽</td><td>75 ₽</td><td>80 ₽</td></tr><tr><td>40 минут</td><td>80 ₽</td><td>100 ₽</td><td>107 ₽</td></tr><tr><td>50 минут</td><td>100 ₽</td><td>125 ₽</td><td>134 ₽</td></tr><tr><td>1 час</td><td>120 ₽</td><td>150 ₽</td><td>160 ₽</td></tr><tr><td>1 час 30 минут</td><td>180 ₽</td><td>225 ₽</td><td>240 ₽</td></tr><tr><td>2 часа</td><td>240 ₽</td><td>300 ₽</td><td>320 ₽</td></tr></tbody></table>\n<blockquote><p><strong>Пакет выгоднее</strong></p><p>Пакет выгоднее для гостя, чем то же время по базовому тарифу. Если гость берёт три часа и больше — предлагайте пакет.</p></blockquote>', 'article', 0, 1, NULL, '2026-08-29T19:25:17.566Z', '2026-08-31T16:41:22.245Z'),
(31, 13, 'Работа с негативом', 'rabota-s-negativom', '<h2>Почему гости жалуются и какая в этом польза</h2>\n<p>Придя в клуб и оплатив игровое время, гости хотят весело провести время. Когда что-то идёт не так, возникает негатив. В момент раздражения людям нужно выплеснуть эмоции, высказаться, и чем громче, тем лучше.</p>\n<p>Негатив — это естественно. Это способность человека не мириться с проблемой, а говорить о ней, требовать решения.</p>\n<blockquote><p><strong>Жалоба — это подарок</strong></p><p>Не оставляй гостя один на один с проблемой — помоги решить её. Он должен чувствовать твоё участие и желание помочь. Жалоба — это возможность стать лучше и удержать гостя. Большинство гостей о проблемах не рассказывают, а молча уходят к конкурентам.</p></blockquote>\n<h2>Ответственность</h2>\n<p>Бери ответственность на себя: не перекладывай её на других или на обстоятельства. Гостю неважно, что пошло не так и кто ошибся, ему важно, чтобы проблему быстро решили. Расскажи, почему возникла проблема (если знаешь причину) и как мы это исправим. Он почувствует твоё участие и будет лояльнее и терпимее.</p>\n<p><strong>Ситуация:</strong> гость пожаловался на грязный стол, крошки и жирные пятна.</p>\n<table><thead><tr><th>Нет</th><th>Да</th></tr></thead><tbody><tr><td>«Это прошлый администратор не убрался. Приносим извинения за доставленные неудобства»<br/>— переложили ответственность на другого администратора;<br/>— извинились формально и неискренне;<br/>— не решили проблему</td><td>«Игорь, извините за грязный стол. Сейчас я его уберу»<br/>— обратились к гостю по имени;<br/>— извинились искренне (живым языком);<br/>— рассказали, как исправим проблему</td></tr></tbody></table>\n<h2>Извинения</h2>\n<p>Если есть наша ошибка, обязательно извинись. А если ошибки нет — посочувствуй гостю и объясни, как работают наши процессы, чтобы сгладить его негатив. Многие решения мы, как бизнес, выбрали специально, поэтому несём за них ответственность и не будем их менять без веских причин. Рассказывай о стандартах и принятых решениях без «может» и «наверное».</p>\n<h2>Не оправдывайся и не спорь</h2>\n<p>Оправдания всегда создают впечатление, что ты ничего не контролируешь и не решаешь. Они заставляют гостя усомниться в твоей компетентности. Помни, что ты лицо клуба: говори уверенно и придерживайся общей политики компании. Не вали вину на других людей или обстоятельства — это признак слабости.</p>\n<p><strong>Ситуация:</strong> несовершеннолетний гость хочет поиграть ночью.</p>\n<table><thead><tr><th>Нет</th><th>Да</th></tr></thead><tbody><tr><td>«У нас нельзя играть после десяти вечера»<br/>— не объяснили, почему отказываем гостю;<br/>— не предложили альтернативу</td><td>«По закону прийти ночью в клуб можно только со взрослыми. Без них мы не сможем вас пустить. В любой момент может прийти полиция с проверкой, и если в клубе будут несовершеннолетние, их заберут в участок и попросят родителей приехать за ними. Также родителей могут оштрафовать. Вы можете либо прийти к нам с законным представителем, либо забронировать игровое место на время, когда не действует комендантский час»<br/>— рассказали, почему мы не разрешаем играть в клубе ночью;<br/>— предложили альтернативу</td></tr></tbody></table>\n<h2>Ошибка гостя</h2>\n<p>Бывают случаи, когда нашей ошибки нет, но есть ошибка гостя: он неверно что-то понял или поторопился, был невнимательным. Не обвиняй его в ошибке: тактично объясни, как всё должно работать, и научи, как действовать правильно, чтобы в следующий раз у него не возникло проблем.</p>\n<h2>Альтернатива</h2>\n<p>Если то, о чём просит гость, невозможно — предложи альтернативу. Сконцентрируй внимание гостя на том, что можно сделать, а не чего нельзя.</p>', 'article', 0, 0, NULL, '2026-08-29T19:25:17.569Z', '2026-08-29T19:25:17.569Z'),
(32, 13, 'Регистрация по паспорту', 'registratsiya-po-pasportu', '<h2>Механика</h2>\n<ul><li><p>Гость, зарегистрированный в системе, автоматически подключается к системе лояльности</p></li><li><p>На бонусный счёт гостя начисляются бонусы, которые он может потратить на покупку игровых часов</p></li><li><p>Чтобы воспользоваться бонусами, нужно пройти идентификацию: назвать свои реальные ФИО, показать паспорт администратору</p></li><li><p>Администратор сохраняет данные в анкете гостя</p></li></ul>\n<h2>Если гость негативит</h2>\n<p>Если гость не хочет показывать паспорт, не даёт согласие на внесение его паспортных данных в систему, следуй памятке.</p>\n<ol>\n<li><p><strong>Прояви эмпатию и посочувствуй гостю.</strong></p><p>Скажи, что понимаешь, как это может быть неудобно. Но регистрацию нужно пройти всего один раз и это займёт 5 минут.</p></li>\n<li><p><strong>Не извиняйся за наше решение ввести регистрацию по паспорту.</strong></p><p>Объясни, почему мы ввели регистрацию и чем это может быть полезно гостю.</p></li>\n<li><p><strong>Если гость всё равно не согласен, не дави на него</strong> и зарегистрируй без паспорта.</p></li>\n</ol>\n<h2>Тезисы для отработки негатива</h2>\n<ol><li><p>По условиям программы лояльности, чтобы воспользоваться бонусами, нужно пройти регистрацию с паспортом</p></li><li><p>Мы ввели новую систему регистрации для безопасности клуба (кражи, умышленная порча техники) и самих гостей: например, если в клубе произойдёт конфликт между гостями, есть возможность идентифицировать злоумышленника</p></li><li><p>Мы не обрабатываем и не передаём данные третьим лицам, а только храним их. Эта информация нужна нам для внутреннего пользования, чтобы идентифицировать игроков</p></li></ol>', 'article', 0, 1, NULL, '2026-08-29T19:25:17.571Z', '2026-08-29T19:25:17.571Z'),
(33, 14, 'Что запрещено администратору', 'chto-zapreshcheno', '<ol><li><p>Занимать игровое место в день отдыха на бесплатной основе в зонах Comfort, VIP, Duo, Trio после 18:00 без согласования с руководством.</p></li><li><p>Играть более двух часов в клубе после завершения смены, если на следующий день заступаешь на смену.</p></li><li><p>Играть на рабочем месте при загрузке клуба более 50%.</p></li><li><p>Покидать рабочее место более чем на 10 минут во время смены. Время смены — с момента принятия смены до её передачи.</p></li><li><p>Использовать ПК в игровом зале в личных целях на смене (штраф 3 000 ₽, повторно — увольнение).</p></li><li><p>Пускать посторонних в админ-комнату (штраф 1 000 ₽, повторно — увольнение).</p></li><li><p>Раскрывать гостям финансовую и внутреннюю информацию клуба (штраф 800 ₽).</p></li><li><p>Нецензурно выражаться при гостях (штраф 600 ₽).</p></li><li><p>Оставлять открытыми технические помещения (штраф 400 ₽).</p></li></ol>\n<blockquote><p><strong>Общий принцип</strong></p><p>За несоблюдение инструкции, невыполнение Задания дня или нарушение Регламента уборки применяются санкции согласно «Листу штрафов». При регулярных нарушениях сотрудник отстраняется от смен с последующим увольнением.</p></blockquote>', 'article', 0, 0, NULL, '2026-08-29T19:25:17.574Z', '2026-08-29T19:25:17.574Z'),
(34, 14, 'Рабочие чаты и отчётность', 'rabochie-chaty', '<p>Все рабочие коммуникации ведутся в рабочих чатах. Администратор обязан держать их открытыми всю смену и оперативно реагировать на сообщения.</p>\n<ul><li><p>Официальные паблики и чат ADMIN NEWS — новости клуба, читать перед каждой сменой и во время неё.</p></li><li><p>Рабочий чат филиала — отчёты по смене, уборке и кассе с хэштегами (см. «Система хэштегов»).</p></li><li><p>Тех. чат — неисправности ПК, периферии и оборудования: фиксируй сразу, как обнаружил.</p></li><li><p>Чат ТП и мониторинг — держать открытыми на смене, оперативно отвечать.</p></li></ul>\n<blockquote data-variant="fine"><p><strong>Штрафы</strong></p><p>Не отписано о завершении задания дня — 200 ₽, повторно — 400 ₽. Расхождение кассы, не отписанное в рабочий чат, — зона ответственности принявшего смену.</p></blockquote>', 'article', 0, 1, NULL, '2026-08-29T19:25:17.575Z', '2026-08-29T19:25:17.575Z'),
(35, 14, 'Система хэштегов', 'sistema-heshtegov', '<p>Хэштеги делают отчёты в рабочих чатах поисковыми: по тегу руководство находит все отчёты филиала. Вместо «Филиал» всегда подставляй название своей точки (Гондатти, Киевская).</p>\n<table><thead><tr><th>Хэштег</th><th>Когда используется</th><th>Что прикладывать</th></tr></thead><tbody><tr><td>#Филиал_Принял (Имя)</td><td>Приём смены после пересчёта кассы</td><td>Фото отчёта LANGAME</td></tr><tr><td>#Филиал_Сдал (Имя)</td><td>Сдача смены</td><td>Фото отчёта LANGAME</td></tr><tr><td>#Филиал_Уборка</td><td>Отчёт о выполнении задания дня</td><td>Описание сделанного + фото (кроме протирки мониторов)</td></tr></tbody></table>\n<blockquote><p><strong>Примеры</strong></p><p>«#Гондатти_Уборка Протер мониторы 25 штук», «#Киевская_Уборка Почистил 4 клавиатуры из 25 [Фото]», «#Гондатти_Принял Иван [Фото отчёта]».</p></blockquote>', 'article', 0, 2, NULL, '2026-08-29T19:25:17.577Z', '2026-08-29T19:25:17.577Z');
