-- GAMER PRO CRM · база данных для MySQL 8 / MariaDB
-- Создано: 07.11.2026 20:38 (Екатеринбург) · источник: gamerpro.sqlite
--
-- Как залить на reg.ru: phpMyAdmin → слева выбрать базу (например u3622481_default) → вкладка «Импорт»
-- → выбрать этот файл → «Вперёд». Затем в config.php на хостинге указать доступы к этой базе.
-- Таблицы портала создаются заново: если они уже были в базе, их содержимое заменится данными из файла.

SET SQL_MODE = 'NO_AUTO_VALUE_ON_ZERO';
SET time_zone = '+00:00';
SET NAMES utf8mb4;
SET FOREIGN_KEY_CHECKS = 0;

-- --------------------------------------------------------
-- Таблица `app_meta`

DROP TABLE IF EXISTS `app_meta`;
CREATE TABLE `app_meta` (
  `k` varchar(64) NOT NULL,
  `v` text DEFAULT NULL,
  PRIMARY KEY (`k`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


-- --------------------------------------------------------
-- Таблица `user`

DROP TABLE IF EXISTS `user`;
CREATE TABLE `user` (
  `id` varchar(64) NOT NULL,
  `name` varchar(191) DEFAULT NULL,
  `email` varchar(191) DEFAULT NULL,
  `emailVerified` tinyint(1) NOT NULL DEFAULT 0,
  `image` text DEFAULT NULL,
  `role` varchar(20) NOT NULL DEFAULT 'admin',
  `permissions` text DEFAULT NULL,
  `scopeBranchId` int DEFAULT NULL,
  `createdAt` varchar(40) DEFAULT NULL,
  `updatedAt` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  UNIQUE KEY `user_email_uq` (`email`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


