-- Таблица `account`

DROP TABLE IF EXISTS `account`;
CREATE TABLE `account` (
  `id` varchar(64) NOT NULL,
  `accountId` varchar(191) DEFAULT NULL,
  `providerId` varchar(64) DEFAULT NULL,
  `userId` varchar(64) DEFAULT NULL,
  `accessToken` text DEFAULT NULL,
  `refreshToken` text DEFAULT NULL,
  `idToken` text DEFAULT NULL,
  `accessTokenExpiresAt` varchar(40) DEFAULT NULL,
  `refreshTokenExpiresAt` varchar(40) DEFAULT NULL,
  `scope` text DEFAULT NULL,
  `password` text DEFAULT NULL,
  `password_php` varchar(255) DEFAULT NULL,
  `createdAt` varchar(40) DEFAULT NULL,
  `updatedAt` varchar(40) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `account_user_idx` (`userId`)
) ENGINE=InnoDB DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_bin;


